---MainMenuAction
---@param id number 打开对话框的id
---@param parm number 参数
---@param excludeDialogs table 要关闭的列表的逻辑
function UIHomeActivityNode:OpenDialogAction(id, parm, excludeDialogs, isShowHomeMain)
    cs_coroutine.start(function()
        CS.UINavigationBarRoot.Instance:SetActive(false)
        coroutine.yield(UIModule.OpenDialog({ id = id, parameters = parm}, checkTable(excludeDialogs)))
        if not isShowHomeMain then
            Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)
        end
        CS.UINavigationBarRoot.Instance:SetActive(true)
    end)
end


function UIHomeActivityNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
